import axios from 'axios';
import puppeteer from 'puppeteer';
import puppeteerCore from 'puppeteer-core';
import chromium from '@sparticuz/chromium';

export interface PostData {
    url: string;
    title: string;
    content: string;
    source: 'blog' | 'cafe';
    date: string;
}

const NAVER_CLIENT_ID = process.env.NAVER_CLIENT_ID || '';
const NAVER_CLIENT_SECRET = process.env.NAVER_CLIENT_SECRET || '';

/**
 * ?ㅼ씠踰?Open API (Search) - 釉붾줈洹??꾩슜
 * 蹂묐젹濡?理쒕? 1000嫄닿퉴吏 ?섏쭛?섏뿬 ?쇨????뺣낫
 */
async function fetchBlogPostsApi(keyword: string, maxItems: number = 1000): Promise<PostData[]> {
    const items: Array<{ link: string; postdate?: string; title: string; description: string }> = [];
    const maxPages = Math.ceil(maxItems / 100);
    const promises = [];

    for (let page = 1; page <= maxPages; page++) {
        const start = ((page - 1) * 100) + 1;
        const url = `https://openapi.naver.com/v1/search/blog.json`;
        promises.push(
            axios.get(url, {
                params: { query: keyword, display: 100, start, sort: 'sim' },
                headers: {
                    'X-Naver-Client-Id': NAVER_CLIENT_ID,
                    'X-Naver-Client-Secret': NAVER_CLIENT_SECRET,
                }
            }).catch(() => {
                return { data: { items: [] } };
            })
        );
    }

    const responses = await Promise.all(promises);
    responses.forEach(res => {
        if (res.data && res.data.items) {
            items.push(...res.data.items);
        }
    });

    // 以묐났 ?쒓굅 諛??щ㎎??r
    const uniqueMap = new Map();
    items.forEach(item => {
        if (!uniqueMap.has(item.link)) {
            const dateStr = item.postdate || '';
            const formattedDate = dateStr.length === 8
                ? `${dateStr.substring(0, 4)}-${dateStr.substring(4, 6)}-${dateStr.substring(6, 8)}`
                : dateStr;

            uniqueMap.set(item.link, {
                url: item.link,
                title: item.title.replace(/<[^>]*>?/g, ''),
                content: item.description.replace(/<[^>]*>?/g, ''),
                source: 'blog',
                date: formattedDate
            });
        }
    });

    return Array.from(uniqueMap.values());
}

/**
 * ?ㅼ씠踰???寃??(?듯빀寃??移댄럹?? - 湲곌컙 寃???듭뀡 ?곸슜
 * Puppeteer瑜??ъ슜??臾댄븳 ?ㅽ겕濡????ㅼ젣 ?뚮뜑留곷맂 嫄댁닔瑜??꾩텧
 */
async function fetchCafePostsWeb(keyword: string, startDate: string, endDate: string): Promise<PostData[]> {
    // startDate, endDate format: "2024-01-01" -> "20240101"
    const startStr = startDate.replace(/-/g, '');
    const endStr = endDate.replace(/-/g, '');

    let browser;
    if (process.env.VERCEL || process.env.NODE_ENV === 'production') {
        chromium.setGraphicsMode = false;
        browser = await puppeteerCore.launch({
            args: [...(chromium as any).args, '--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage', '--blink-settings=imagesEnabled=false'],
            defaultViewport: (chromium as any).defaultViewport,
            executablePath: await chromium.executablePath(),
            headless: (chromium as any).headless,
        });
    } else {
        browser = await puppeteer.launch({
            headless: true,
            args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage', '--blink-settings=imagesEnabled=false']
        });
    }

    let items: PostData[] = [];

    try {
        const page = await browser.newPage();
        await page.setViewport({ width: 1280, height: 1024 });

        // CSS, ?고듃 ?붿껌 ?꾨㈃ 李⑤떒?섏뿬 援щ룞 ?띾룄 洹밸???r
        await page.setRequestInterception(true);
        page.on('request', (req) => {
            if (['image', 'stylesheet', 'font', 'media'].includes(req.resourceType())) {
                req.abort();
            } else {
                req.continue();
            }
        });

        const url = `https://search.naver.com/search.naver?ssc=tab.cafe.all&query=${encodeURIComponent(keyword)}&sm=tab_opt&nso=so:r,p:from${startStr}to${endStr}`;
        await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 15000 });

        let prevHeight = 0;
        let noChangeCount = 0;
        const MAX_SCROLL_ATTEMPTS = 50; // 移댄럹 寃곌낵媛 諛⑸???寃쎌슦瑜??鍮꾪빐 ?ㅽ겕濡?理쒕? ?잛닔 吏??r
        let scrolls = 0;

        while (scrolls < MAX_SCROLL_ATTEMPTS) {
            await page.evaluate(() => document.body.scrollHeight);
            await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));

            // ?ㅼ씠踰?寃??寃곌낵 鍮꾨룞湲??뚮뜑留??湲?r
            await new Promise(r => setTimeout(r, 600));

            const newHeight = await page.evaluate(() => document.body.scrollHeight);
            if (newHeight === prevHeight) {
                noChangeCount++;
                if (noChangeCount >= 3) break; // 3踰??쒕룄?대룄 ??諛붾떏?????대젮媛硫???(?뚮뜑 ?꾨즺)
            } else {
                noChangeCount = 0;
                prevHeight = newHeight;
            }
            scrolls++;
        }

        // ?뚮뜑留곷맂 紐⑤뱺 移댄럹湲(.title_area ?덉쓽 .title_link) 異붿텧
        const pageData = await page.evaluate(() => {
            const results: { title: string; url: string }[] = [];
            document.querySelectorAll('.title_area .title_link').forEach(el => {
                results.push({
                    title: (el as HTMLElement).innerText.trim(),
                    url: (el as HTMLAnchorElement).href,
                });
            });
            return results;
        });

        // ?꾨줎?몄뿏???⑹궛???꾪빐 ?붾? Data ?щ㎎ 留욎텛湲? (?좎쭨???대? ?ㅼ씠踰?湲곌컙 ?寃??꾪꽣???섏〈?섎?濡?援녹씠 ?뚯떛?덊븿)
        items = pageData.map(data => ({
            url: data.url,
            title: data.title,
            content: '',
            source: 'cafe',
            date: startDate // 湲곌컙 寃???꾪꽣濡?李얠븯湲??뚮Ц???꾨? ?덉슜?쒕떎怨?媛?뺥븯怨??듦낵瑜??꾪빐 startDate濡?吏??
        }));

    } catch (e) {
        console.error("Puppeteer 移댄럹 寃???ㅽ겕濡??ㅻ쪟:", e);
    } finally {
        await browser.close();
    }

    return items;
}

/**
 * 
 * 1. 釉붾줈洹? API 1000嫄?蹂묐젹 (?띾룄 媛??鍮좊Ⅴ怨??덉젙??
 * 2. 移댄럹: ?ㅼ씠踰??듯빀寃?????섏씠吏 ?щ·留?(湲곌컙 ?듭뀡 ?곸슜, ?ㅼ씠?섎? ?ㅽ겕濡ㅻ쭅 移댁슫??
 */
export async function crawlSocialData(keyword: string, startDate: string, endDate: string): Promise<PostData[]> {
    const results: PostData[] = [];

    const [blogItems, cafeItems] = await Promise.all([
        fetchBlogPostsApi(keyword, 1000),
        fetchCafePostsWeb(keyword, startDate, endDate)
    ]);

    // 釉붾줈洹몃뒗 ?좎쭨 ?뺣낫媛 ?덉쑝誘濡?理쒖쥌 ?寃?湲곌컙 ?꾪꽣留??꾨즺
    const filteredBlog = blogItems.filter(item => item.date >= startDate && item.date <= endDate);

    // 移댄럹??釉뚮씪?곗? ?ㅼ씠踰?寃??`nso=p:from...to...` ?먯껜 ?꾪꽣???섏〈?섎?濡??대? ?좏슚
    results.push(...filteredBlog, ...cafeItems);

    return results;
}
